public PiggyBankBlock(@Nullable DyeColor color) {
        super(FabricBlockSettings.create().strength(1.25F, 4.2F));
        this.color = color;
    }

public static ItemStack getPiggy(@Nullable DyeColor color) {
        if (color == null) return new ItemStack(PIGGY_BANK);

        return switch (color) {
            case WHITE -> new ItemStack(NumismaticOverhaulBlocks.WHITE_PIGGY_BANK);
            case ORANGE -> new ItemStack(NumismaticOverhaulBlocks.ORANGE_PIGGY_BANK);
            case MAGENTA -> new ItemStack(NumismaticOverhaulBlocks.MAGENTA_PIGGY_BANK);
            case LIGHT_BLUE -> new ItemStack(NumismaticOverhaulBlocks.LIGHT_BLUE_PIGGY_BANK);
            case YELLOW -> new ItemStack(NumismaticOverhaulBlocks.YELLOW_PIGGY_BANK);
            case LIME -> new ItemStack(NumismaticOverhaulBlocks.LIME_PIGGY_BANK);
            case PINK -> new ItemStack(NumismaticOverhaulBlocks.PINK_PIGGY_BANK);
            case GRAY -> new ItemStack(NumismaticOverhaulBlocks.GRAY_PIGGY_BANK);
            case LIGHT_GRAY -> new ItemStack(NumismaticOverhaulBlocks.LIGHT_GRAY_PIGGY_BANK);
            case CYAN -> new ItemStack(NumismaticOverhaulBlocks.CYAN_PIGGY_BANK);
            case PURPLE -> new ItemStack(NumismaticOverhaulBlocks.PURPLE_PIGGY_BANK);
            case BLUE -> new ItemStack(NumismaticOverhaulBlocks.BLUE_PIGGY_BANK);
            case BROWN -> new ItemStack(NumismaticOverhaulBlocks.BROWN_PIGGY_BANK);
            case GREEN -> new ItemStack(NumismaticOverhaulBlocks.GREEN_PIGGY_BANK);
            case RED -> new ItemStack(NumismaticOverhaulBlocks.RED_PIGGY_BANK);
            case BLACK -> new ItemStack(NumismaticOverhaulBlocks.BLACK_PIGGY_BANK);
        };
    }

@Override
    protected void appendProperties(StateManager.Builder<Block, BlockState> builder) {
        builder.add(FACING);
    }

@Nullable
    @Override
    public BlockState getPlacementState(ItemPlacementContext ctx) {
        return this.getDefaultState().with(FACING, ctx.getHorizontalPlayerFacing().getOpposite());
    }

@Override
    public VoxelShape getOutlineShape(BlockState state, BlockView world, BlockPos pos, ShapeContext context) {
        return switch (state.get(FACING)) {
            case SOUTH -> SOUTH_SHAPE;
            case WEST -> WEST_SHAPE;
            case EAST -> EAST_SHAPE;
            default -> NORTH_SHAPE;
        };
    }

@Override
    public ActionResult onUse(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit) {

        if (!world.isClient) {
            if (world.getBlockEntity(pos) instanceof NamedScreenHandlerFactory factory) {
                player.openHandledScreen(factory);
            }
        }

        return ActionResult.SUCCESS;
    }

@Override
    public void onLandedUpon(World world, BlockState state, BlockPos pos, Entity entity, float fallDistance) {
        if (entity instanceof FallingBlockEntity fallingBlock && fallingBlock.getBlockState().isIn(NumismaticOverhaul.VERY_HEAVY_BLOCKS) && !world.isClient) {
            if (world.getBlockEntity(pos) instanceof PiggyBankBlockEntity piggyBank) {
                ItemScatterer.spawn(world, pos.offset(world.getBlockState(pos).get(FACING).getOpposite()), piggyBank.inventory());
            }

            world.removeBlock(pos, false);

            WorldOps.playSound(world, pos, NumismaticOverhaul.PIGGY_BANK_BREAK, SoundCategory.BLOCKS);
            NumismaticOverhaul.PIGGY_BANK_BROKEN.spawn(world, Vec3d.of(pos), Math.round(fallDistance));
        }

        super.onLandedUpon(world, state, pos, entity, fallDistance);
    }

@Override
    public void onBreak(World world, BlockPos pos, BlockState state, PlayerEntity player) {
        if (world.getBlockEntity(pos) instanceof PiggyBankBlockEntity piggyBank && player.isCreative() && !world.isClient && !piggyBank.inventory().stream().allMatch(ItemStack::isEmpty)) {
            ItemStack stack;
            if (piggyBank.getColor() == null) {
                stack = new ItemStack(PIGGY_BANK);
            } else {
                stack = getPiggy(color);
            }
            piggyBank.setStackNbt(stack);

            ItemEntity var = new ItemEntity(world, pos.getX() + .5d, pos.getY() + .5d, pos.getZ() + .5d, stack);
            var.setToDefaultPickupDelay();
            world.spawnEntity(var);
        }

        super.onBreak(world, pos, state, player);
    }

@Override
    public List<ItemStack> getDroppedStacks(BlockState state, LootContextParameterSet.Builder builder) {
        if (builder.getOptional(LootContextParameters.BLOCK_ENTITY) instanceof PiggyBankBlockEntity piggyBank) {
            var tool = builder.getOptional(LootContextParameters.TOOL);
            if (tool != null && tool.hasCustomName() && Objects.equals(tool.getName().getString(), "Hammer")) {

                WorldOps.playSound(piggyBank.getWorld(), piggyBank.getPos(), NumismaticOverhaul.PIGGY_BANK_BREAK, SoundCategory.BLOCKS);
                NumismaticOverhaul.PIGGY_BANK_BROKEN.spawn(piggyBank.getWorld(), Vec3d.of(piggyBank.getPos()), 5);

                var drops = new ArrayList<>(super.getDroppedStacks(state, builder));
                piggyBank.inventory().stream().filter(stack -> !stack.isEmpty()).forEach(drops::add);
                return drops;
            } else {
                builder.addDynamicDrop(new Identifier("contents"), (consumer) -> {
                    piggyBank.inventory().forEach(consumer);
                });
            }
        }

        return super.getDroppedStacks(state, builder);
    }

@Nullable
    @Override
    public BlockEntity createBlockEntity(BlockPos pos, BlockState state) {
        return new PiggyBankBlockEntity(this.color, pos, state);
    }

public PiggyBankBlockEntity(BlockPos pos, BlockState state) {
        super(NumismaticOverhaulBlocks.Entities.PIGGY_BANK, pos, state);
        this.color = null;
    }

public PiggyBankBlockEntity(@Nullable DyeColor color, BlockPos pos, BlockState state) {
        super(NumismaticOverhaulBlocks.Entities.PIGGY_BANK, pos, state);
        this.color = color;
    }

@Override
    public void readNbt(NbtCompound nbt) {
        super.readNbt(nbt);

        this.inventory.clear();
        Inventories.readNbt(nbt, this.inventory);
    }

@Override
    protected void writeNbt(NbtCompound nbt) {
        super.writeNbt(nbt);
        Inventories.writeNbt(nbt, this.inventory);
    }

@Override
    public Text getDisplayName() {
        return this.getCachedState().getBlock().getName();
    }

public DefaultedList<ItemStack> inventory() {
        return this.inventory;
    }

public DyeColor getColor() {
        return color;
    }

@Nullable
    @Override
    public ScreenHandler createMenu(int syncId, PlayerInventory inv, PlayerEntity player) {
        return new PiggyBankScreenHandler(
                syncId,
                player.getInventory(),
                ScreenHandlerContext.create(this.world, this.pos),
                (ImplementedInventory) () -> PiggyBankBlockEntity.this.inventory
        );
    }

public PiggyBankColoringRecipe(Identifier id, CraftingRecipeCategory category) {
        super(id, category);
    }

public boolean matches(RecipeInputInventory recipeInputInventory, World world) {
        int i = 0;
        int j = 0;

        for (int k = 0; k < recipeInputInventory.size(); ++k) {
            ItemStack itemStack = recipeInputInventory.getStack(k);
            if (!itemStack.isEmpty()) {
                if (Block.getBlockFromItem(itemStack.getItem()) instanceof PiggyBankBlock) {
                    ++i;
                } else {
                    if (!(itemStack.getItem() instanceof DyeItem)) {
                        return false;
                    }

                    ++j;
                }

                if (j > 1 || i > 1) {
                    return false;
                }
            }
        }

        return i == 1 && j == 1;
    }

public ItemStack craft(RecipeInputInventory recipeInputInventory, DynamicRegistryManager dynamicRegistryManager) {
        ItemStack itemStack = ItemStack.EMPTY;
        DyeItem dyeItem = (DyeItem) Items.WHITE_DYE;

        for (int i = 0; i < recipeInputInventory.size(); ++i) {
            ItemStack itemStack2 = recipeInputInventory.getStack(i);
            if (!itemStack2.isEmpty()) {
                Item item = itemStack2.getItem();
                if (Block.getBlockFromItem(item) instanceof PiggyBankBlock) {
                    itemStack = itemStack2;
                } else if (item instanceof DyeItem) {
                    dyeItem = (DyeItem) item;
                }
            }
        }

        ItemStack itemStack3 = PiggyBankBlock.getPiggy(dyeItem.getColor());
        if (itemStack.hasNbt()) {
            itemStack3.setNbt(itemStack.getNbt().copy());
        }

        return itemStack3;
    }

@Override
    public boolean fits(int width, int height) {
        return width * height >= 2;
    }

@Override
    public RecipeSerializer<?> getSerializer() {
        return NumismaticOverhaul.PIGGY_BANK_COLORING_RECIPE;
    }
